 import unittest
from candidate import filter_by_substring

class TestFilterBySubscription(unittest.TestCase):
    def test_filter_empty_list(self):
        self.assertEqual(filter_by_substring([], 'a'), [])

    def test_filter_no_substring(self):
        self.assertEqual(filter_by_substring(['abc', 'bacd', 'cde', 'array'], 'z'), [])

    def test_filter_substring_in_all_elements(self):
        self.assertEqual(filter_by_substring(['abc', 'bacd', 'cde', 'array'], 'a'), ['abc', 'bacd', 'array'])

    def test_filter_substring_in_some_elements(self):
        self.assertEqual(filter_by_subscription(['abc', 'bacd', 'cde', 'array'], 'c'), ['bacd', 'cde'])

    def test_filter_substring_in_first_element(self):
        self.assertEqual(filter_by_subscription(['abc', 'bacd', 'cde', 'array'], 'b'), ['abc', 'bacd'])

    def test_filter_substring_in_last_element(self):
        self.assertEqual(filter_by_subscription(['abc', 'bacd', 'cde', 'array'], 'y'), ['array'])

    def test_filter_substring_in_multiple_elements(self):
        self.assertEqual(filter_by_subscription(['abc', 'bacd', 'cde', 'array', 'zabc'], 'a'), ['abc', 'zabc'])

    def test_filter_substring_as_empty_string(self):
        self.assertEqual(filter_by_subscription(['abc', 'bacd', 'cde', 'array'], ''), ['abc', 'bacd', 'cde', 'array'])

    def test_filter_substring_with_none(self):
        self.assertEqual(filter_by_subscription(['abc', 'bacd', 'cde', 'array'], None), [])

    def test_filter_substring_with_non_string(self):
        with self.assertRaises(TypeError):
            filter_by_subscription(['abc', 'bacd', 'cde', 'array'], 1)

if __name__ == '__main__':
    unittest.main()
